!function(t){function r(r){for(var n,a,p=r[0],m=r[1],s=r[2],c=0,l=[];c<p.length;c++)a=p[c],Object.prototype.hasOwnProperty.call(i,a)&&i[a]&&l.push(i[a][0]),i[a]=0;for(n in m)Object.prototype.hasOwnProperty.call(m,n)&&(t[n]=m[n]);for(u&&u(r);l.length;)l.shift()();return o.push.apply(o,s||[]),e()}function e(){for(var t,r=0;r<o.length;r++){for(var e,a=o[r],p=!0,m=1;m<a.length;m++)e=a[m],0!==i[e]&&(p=!1);p&&(o.splice(r--,1),t=n(n.s=a[0]))}return t}function n(r){if(a[r])return a[r].exports;var e=a[r]={i:r,l:!1,exports:{}};return t[r].call(e.exports,e,e.exports,n),e.l=!0,e.exports}var a={},i={16:0},o=[];n.m=t,n.c=a,n.d=function(t,r,e){n.o(t,r)||Object.defineProperty(t,r,{enumerable:!0,get:e})},n.r=function(t){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(t,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(t,"__esModule",{value:!0})},n.t=function(t,r){if(1&r&&(t=n(t)),8&r)return t;if(4&r&&"object"==typeof t&&t&&t.__esModule)return t;var e=Object.create(null);if(n.r(e),Object.defineProperty(e,"default",{enumerable:!0,value:t}),2&r&&"string"!=typeof t)for(var a in t)n.d(e,a,function(r){return t[r]}.bind(null,a));return e},n.n=function(t){var r=t&&t.__esModule?function(){return t.default}:function(){return t};return n.d(r,"a",r),r},n.o=function(t,r){return Object.prototype.hasOwnProperty.call(t,r)},n.p="";var p=window.webpackJsonp=window.webpackJsonp||[],m=p.push.bind(p);p.push=r,p=p.slice();for(var s=0;s<p.length;s++)r(p[s]);var u=m;o.push([21,0]),e()}({21:function(t,r,e){"use strict";e.r(r);var n=e(0);Object(n.a)("us","army",e(22),e(1))},22:function(t){t.exports=JSON.parse('{"category":[{"name":"美国","link":"us_shortcut"},{"name":"陆战武器","link":"us_army"},{"name":"坦克","link":"us_army#us_army_tank"}],"model":"M24轻型坦克","description":"<h6>综述：</h6><p>1942年，通过实战证明，M3/M5轻型坦克的37mm火炮的火力实在太弱，美军迫切要求在坦克换装更大口径的火炮，但M3A3和M5A1炮塔都太小，无法进行改装，于是美国就重新研制了一种新型号的坦克，装上76mm火炮，1943年正式定名为M24，并以号称美军装甲兵之父霞飞将军名字命名，以取代M3/M5轻型坦克。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"{{text}}M24“霞飞”轻型坦克{{image}}imgs/us/army/us_army_tankm24_11.jpg{{text}}1944年，美军的M24“霞飞”轻型坦克。{{image}}imgs/us/army/us_army_tankm24_12.jpg{{text}}1945年，美军的M24“霞飞”轻型坦克。{{image}}imgs/us/army/us_army_tankm24_13.jpg","description":"<h6>M24轻型坦克</h6><p>M24轻型坦克是美国传统式的单炮塔坦克。它的火力和装甲相比二战各国的轻型坦克中，应是最强大的；它采用了新型的悬挂系统，换装了一门射速较高的75mm火炮，炮塔也增大了，车重有18t（接近中型坦克的车重了），但在两台凯迪拉克改动机的驱动下，仍能有55km/h的车速；限于车重，装甲厚度受到限制，车体前装甲厚度只有38mm，但在大倾角的结构下，也完全能防御小口径反坦克炮的攻击。</p><p>坦克参数（供参考）：</p><p>车长：5.48m, 车宽：2.95m, 车高：2.46m, 车重：18.37t；乘员5人。</p><p>发动机功率：330匹马力，车速：55km/h, 最大行程：240km。</p><p>装甲厚度：12-38mm，武器配备：1门75mm M6火炮，2挺7.62mm机枪和1挺12.7mm M2高射机枪。</p><p>二战期间，美国一共生产了4731辆M24轻型坦克。</p><span class=\'custom-document-caption text-secondary\'><strong>外形特点：</strong><ol><li>悬挂系统两侧各有5个大口径负重轮。</li><li>单炮塔，车体前甲板装有1挺前射机枪。主炮右侧装有一挺并列民机枪。</li><li>炮塔上部有一个圆形顶窗。</li></ol></span>","caption":""}],"part2title":"战场上的M24“霞飞”轻型坦克","part2description":"<p>M24轻型坦克在1944年开始装备在欧洲战场上作战的美军，虽然它装甲薄弱，火力在二战末期也不算强大，但凭着它良好的整体性能，在当时仍然得到美军的好评。1945年3月在德国战场，美军第4骑兵侦察营F连的M24轻型坦克突遇德军二辆虎式坦克，在双方毫无准备的情况下，美军M24凭借良好的机动性能，抢到了德军的虎式坦克的侧面，并以较快的炮塔转速将火炮瞄准了虎式坦克的炮塔和车体开火，虽然未能直接击穿虎式坦克的装甲，但却引燃了坦克内的燃油造成内部弹药爆炸，成功地将其摧毁。M24轻型坦克虽参加了占领日本本土的行动，但却未参加过太平洋的夺岛战斗。二战期间，曾有数量不多的M24轻型坦克提供给英军作战，但战后却有多个国家获得此坦克，但M24在1950年朝鲜战场上，却被苏制的T34坦克压制，战损严重。</p>","part2content":[{"image":"imgs/us/army/us_army_tankm24_21.jpg","description":"在公路上行驶的M24轻型坦克。","caption":""},{"image":"imgs/us/army/us_army_tankm24_22.jpg","description":"在泥泞中行驶的M24轻型坦克。","caption":""},{"image":"imgs/us/army/us_army_tankm24_23.jpg","description":"1945年，在萨尔茨堡外围以战斗姿态前进的M24轻型坦克。","caption":""},{"image":"imgs/us/army/us_army_tankm24_24.jpg","description":"1945年3月26日，在穿越莱茵河行动期间，美军第30师120步兵团一支步枪排的指挥小组在744轻型坦克营的M24轻型坦克掩护下通过Wesel森林。","caption":""},{"image":"imgs/us/army/us_army_tankm24_25.jpg","description":"1945年德国，一位苏军军官正在M24轻型坦克上与美军交流。","caption":""},{"image":"imgs/us/army/us_army_tankm24_26.jpg","description":"一辆M24轻型坦克成员在战斗间隙中休息。","caption":""},{"image":"imgs/us/army/us_army_tankm24_27.jpg","description":"一支配备M24轻型坦克的美军部队在行进中的。","caption":""}]}')}});